<script lang="ts">
 import {onMount} from 'svelte';import {Api} from '$lib/api';let query=$state('');let result=$state<any>(null);let error=$state('');let history=$state<any[]>([]);
 async function lookup(){try{result=await Api.aircraftLookup(query.trim());if(result!=null)history=[result,...history].slice(0,20);error=''}catch(e){error=String(e)}}onMount(async()=>{try{result=await Api.aircraftLookup('')}catch{}});
</script>
<div class="page"><h1>Aircraft Lookup</h1><p class="muted">Resolve an ICAO hex address, registration or callsign.</p><section class="card search"><input bind:value={query} placeholder="ICAO, registration or callsign" onkeydown={(e)=>e.key==='Enter'&&lookup()}/><button class="primary" onclick={lookup}>Lookup</button></section>{#if error}<p class="error">{error}</p>{/if}{#if result}<section class="card"><h2>Result</h2><div class="fields">{#each Object.entries(result) as [k,v]}<span><small>{k}</small>{typeof v==='object'?JSON.stringify(v):String(v??'—')}</span>{/each}</div></section>{/if}<section class="card"><h2>Recent results</h2>{#each history as item}<pre>{JSON.stringify(item,null,2)}</pre>{:else}<div class="empty">No lookups yet</div>{/each}</section></div>
<style>.page{padding:16px;overflow-y:auto;height:100%}.muted,small,.empty{color:var(--fg-dim)}.error{color:var(--danger)}.card{margin:12px 0;padding:14px;background:var(--bg-elev);border:1px solid var(--line);border-radius:8px}.search{display:flex;gap:8px}input,button{background:var(--bg);color:var(--fg);border:1px solid var(--line);padding:8px 10px;border-radius:5px}input{flex:1}.primary{color:var(--accent);border-color:var(--accent)}h2{font-size:14px}.fields{display:flex;gap:18px;flex-wrap:wrap;font:12px var(--mono)}.fields span{min-width:130px}.fields small{display:block;font:10px var(--sans)}pre{background:var(--bg);padding:8px;white-space:pre-wrap;font:11px var(--mono)}.empty{text-align:center;padding:18px}</style>
